/* Parse Facebook Messenger webhook -> one item per incoming message
 * Output: { userId, text, messageType, messageId, mediaUrl?, mediaPreviewUrl?, seq }
 * ???????????? echo (?????????????????????????????????????????????????????????????????????????????????????????????) ????????? event ????????????????????????????????????????????????
 */
const body = $('Webhook').first().json.body || {};
const entries = Array.isArray(body.entry) ? body.entry : [];
const out = [];
let seq = 0;

for (const entry of entries) {
  const messaging = Array.isArray(entry.messaging) ? entry.messaging : [];
  for (const m of messaging) {
    if (!m || !m.message) { continue; }
    if (m.message.is_echo) { continue; }
    const userId = (m.sender && m.sender.id) ? m.sender.id : '';
    if (!userId) { continue; }

    const msg = m.message;
    const atts = Array.isArray(msg.attachments) ? msg.attachments : [];
    let mtype = 'text';
    let text = '';
    if (atts.length > 0) {
      const a = atts[0];
      const t = a.type || 'file';
      mtype = t;
      if (t === 'image')       { text = '[?????????]'; }
      else if (t === 'video')  { text = '[??????????????????]'; }
      else if (t === 'audio')  { text = '[???????????????]'; }
      else if (t === 'file')   { text = '[????????????]'; }
      else if (t === 'location') { text = '[?????????????????????]'; }
      else                     { text = '[' + t + ']'; }
    } else if (typeof msg.text === 'string') {
      text = msg.text.trim();
    }
    if (!text) { continue; }

    const item = {
      userId: userId,
      text: text,
      messageType: mtype,
      messageId: msg.mid || '',
      seq: seq++,
    pageId: entry.id || '',
    };
    if (atts.length > 0 && atts[0].payload && atts[0].payload.url) {
      item.mediaUrl = atts[0].payload.url;
      item.mediaPreviewUrl = atts[0].payload.url;
    }
    out.push({ json: item });
  }
}
return out;

/* Forward to ChatDesk incoming.php (channel=fb) ??????????????? media URL ??????????????????????????? FB ????????? ??? */
const cfg      = $('Set Config').first().json;
const events   = $('Parse FB Events').all();   // ??????????????????????????? parse ?????? (???????????????????????? entry order)
let profiles = []; try { profiles = $('Get FB Profile').all(); } catch(e) { profiles = []; }                 // Get FB Profile output 1:1 ???????????????????????? item

const out = [];
for (let i = 0; i < events.length; i++) {
  const ev = events[i].json || {};
  const pr = (profiles[i] && profiles[i].json) ? profiles[i].json : {};
  const firstName   = pr.first_name || '';
  const lastName    = pr.last_name || '';
  const displayName = [firstName, lastName].filter(Boolean).join(' ');
  const pictureUrl  = pr.profile_pic || '';

  let botEnabled = true;
  const payload = {
    userId: ev.userId,
    text: ev.text,
    sender: 'customer',
    messageId: ev.messageId,
    messageType: ev.messageType,
    channel: ($('Shape Channel FB').first().json.channel_code || 'fbchat'),
  };
  if (ev.mediaUrl) {
    payload.mediaUrl = ev.mediaUrl;
    payload.mediaPreviewUrl = ev.mediaPreviewUrl || ev.mediaUrl;
  }
  if (displayName) { payload.displayName = displayName; }
  if (pictureUrl)  { payload.pictureUrl = pictureUrl; }
  if (cfg.CHATDESK_SECRET) { payload.secret = cfg.CHATDESK_SECRET; }

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', url: cfg.CHATDESK_URL, json: true, timeout: 20000, body: payload,
    });
    botEnabled = !(res && res.botEnabled === false);
  } catch (err) {
    botEnabled = true;
  }

  out.push({ json: {
    userId: ev.userId,
    text: ev.text,
    displayName: displayName,
    channel: ($('Shape Channel FB').first().json.channel_code || 'fbchat'),
    botEnabled: botEnabled,
    isText: ev.messageType === 'text',
  } });
}

return out;

/* Take AI/LLM output, attach userId, carry RAG image URLs (public https only, max 4) */
const items = $input.all();
const out = [];
let imgs = [];
try { imgs = ($('Attach RAG').first().json.rag_images || []); } catch (err) { imgs = []; }
try { const sq = ($('Merge Shop SQL').first().json.sql_images || []); if (Array.isArray(sq)) imgs = imgs.concat(sq); } catch (err2) {}
if (!Array.isArray(imgs)) imgs = [];
let pubBase = '';
try { pubBase = ($('Set Config').first().json.PUBLIC_WEB_BASE || '').toString().replace(/\/$/, ''); } catch (err3) {}
const seen = {};
imgs = imgs.map(u => { u = (u || '').toString().trim(); if (pubBase && /^http:\/\/127\.0\.0\.1:8081\//i.test(u)) u = pubBase + u.slice(21); return u; }).filter(u => /^https:\/\//i.test(u) && !seen[u] && (seen[u] = 1)).slice(0, 4);
for (let i = 0; i < items.length; i++) {
  let userId = '';
  try { userId = $('Send to ChatDesk').itemMatching(i).json.userId || ''; } catch (err) { userId = ''; }
  const raw = items[i].json.output || items[i].json.text || '';
  const replyText = String(raw).replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  if (userId && replyText) { out.push({ json: { userId: userId, replyText: replyText, images: imgs } }); }
}
return out;

/* Build Facebook Messenger Graph API payload from bot reply (text only) */
const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json || {};
  if (!j.userId || !j.replyText) { continue; }
  out.push({ json: {
    recipient: { id: j.userId },
    message: { text: j.replyText },
    messaging_type: 'RESPONSE',
  } });
  const imgs = Array.isArray(j.images) ? j.images : [];
  for (const u of imgs.slice(0, 3)) {
    const url = (u || '').toString().trim();
    if (!/^https:\/\//i.test(url)) { continue; }
    out.push({ json: {
      recipient: { id: j.userId },
      message: { attachment: { type: 'image', payload: { url: url, is_reusable: true } } },
      messaging_type: 'RESPONSE',
    } });
  }
}
return out;

/* Save bot reply into ChatDesk so it shows in agent inbox */
const cfg = $('Set Config').first().json;

for (const item of $('Build Reply').all()) {
  const j = item.json || {};
  if (!j.userId || !j.replyText) { continue; }
  const payload = { userId: j.userId, text: j.replyText, sender: 'bot', channel: $('Shape Channel FB').first().json.channel_code || 'line' };
  if (cfg.CHATDESK_SECRET) { payload.secret = cfg.CHATDESK_SECRET; }
  const res = await this.helpers.httpRequest({
    method: 'POST', url: cfg.CHATDESK_URL, json: true, timeout: 20000, body: payload,
  });
  if (!res || res.ok !== true) {
    throw new Error('ChatDesk save failed: ' + JSON.stringify(res));
  }
  const imgs = Array.isArray(j.images) ? j.images : [];
  for (const u of imgs.slice(0, 4)) {
    const url = (u || '').toString().trim();
    if (!/^https:\/\//i.test(url)) { continue; }
    const ipayload = { userId: j.userId, text: url, sender: 'bot', channel: $('Shape Channel FB').first().json.channel_code || 'line', messageType: 'image', mediaUrl: url, mediaPreviewUrl: url };
    if (cfg.CHATDESK_SECRET) { ipayload.secret = cfg.CHATDESK_SECRET; }
    await this.helpers.httpRequest({ method: 'POST', url: cfg.CHATDESK_URL, json: true, timeout: 20000, body: ipayload });
  }
}

return $input.all();

const cfg = $('Set Config').first().json;
const code = ((cfg.CHANNEL_CODE || 'fbchat') + '').replace(/'/g, "''");
const sel = `SELECT m.channel_code, COALESCE(m.persona_system, '') AS persona_system, COALESCE((SELECT json_agg(group_id ORDER BY group_id) FROM channel_rag_groups WHERE channel_code = m.channel_code), '[]') AS group_ids FROM channel_map m`;
return [{ json: { sql: `SELECT COALESCE((SELECT json_agg(row_to_json(t)) FROM (${sel} WHERE m.channel_code = '${code}') t), '[]') AS rows` } }];

const r0 = $input.first().json;
let rows = r0.rows || [];
if (typeof rows === 'string') { try { rows = JSON.parse(rows); } catch(e) { rows = []; } }
const r = rows[0] || {};
const parseIds = function(v){ try {
  if (Array.isArray(v)) return v.map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; });
  if (typeof v === 'string' && v.trim() !== '') return JSON.parse(v).map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; });
} catch(e){} return []; };
return [{ json: {
  channel_code: (r.channel_code || 'fbchat').toString(),
  group_ids: parseIds(r.group_ids),
  persona_system: (r.persona_system || '').toString() } }];

const items = $input.all().map(r => r.json);
const orig = items.find(r => r.text !== undefined && r.ok === undefined) || {};
const rag = items.find(r => r.ok !== undefined) || {};
const rc = (rag.text || '').toString();
const rimgs = Array.isArray(rag.images) ? rag.images.map(u => (u || '').toString().trim()).filter(u => u !== '') : [];
return [{ json: { ...orig, rag_context: rc, rag_sources: rag.sources || [], rag_images: rimgs } }];

/* Merge Attach RAG item with Shop SQL result; decide deterministic SQL reply */
const a = $('Attach RAG').first().json;
let s = {};
try { s = $('Shop SQL Lookup').first().json || {}; } catch (e) { s = {}; }
const sql_rows = parseInt(s.rows) || 0;
const sql_answer = (s.answer || '').toString();
const sql_block = (s.block || '').toString();
let sql_images = [];
try {
  const arr = s.images;
  if (Array.isArray(arr)) sql_images = arr.map(u => (u || '').toString().trim()).filter(u => /^https?:\/\//i.test(u)).slice(0, 4);
} catch (e2) { sql_images = []; }
const adviceQ = /(\u0e41\u0e19\u0e30\u0e19\u0e33|\u0e40\u0e1b\u0e23\u0e35\u0e22\u0e1a\u0e40\u0e17\u0e35\u0e22\u0e1a|\u0e40\u0e1b\u0e23\u0e35\u0e22\u0e1a|\u0e04\u0e38\u0e49\u0e21|\u0e14\u0e35\u0e44\u0e2b\u0e21|\u0e40\u0e25\u0e37\u0e2d\u0e01|\u0e15\u0e31\u0e27\u0e44\u0e2b\u0e19|\u0e23\u0e38\u0e48\u0e19\u0e44\u0e2b\u0e19|\u0e14\u0e35\u0e01\u0e27\u0e48\u0e32)/.test(a.text || '');
const sql_direct = sql_rows > 0 && sql_answer !== '' && !adviceQ;
return [{ json: { ...a, sql_block, sql_answer, sql_images, sql_rows, sql_direct } }];

/* Deterministic product answer from Shop SQL (skip LLM) */
const m = $('Merge Shop SQL').first().json;
return [{ json: { output: (m.sql_answer || '').toString().slice(0, 2000) } }];

const it = $input.first().json;
let t = '';
try { t = ((it.message || {}).content || '').toString(); } catch(e) {}
t = t.replace(/^[\s\S]*?<\/think>/, '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
if (!t) throw new Error('Local LLM ไม่ตอบ');
return [{ json: { output: t.slice(0, 2000) } }];

const a = $('Attach RAG').first().json;
const dn = ((a.displayName || '') + '') || 'ลูกค้าท่านนี้';
const SYSJS = "=คุณคือผู้ช่วยตอบแชทของร้าน/องค์กรบน LINE (ChatDesk)\nกรุณาตอบลูกค้าด้วยภาษาไทยที่สุภาพ กระชับ และช่วยเหลือได้จริง ตามข้อมูลของร้านที่มีอยู่\nถ้าลูกค้าถามเรื่องที่ไม่อยู่ในข้อมูล ให้แนะนำให้ติดต่อเจ้าหน้าที่หรือตอบว่าไม่ทราบ พร้อมเสนอช่วยเรื่องอื่น\nใช้ถ้อยคำที่เป็นธรรมชาติเหมือนพูดกับลูกค้า ไม่ใช้ศัพท์เทคนิคเกินจำเป็น\nชื่อลูกค้า (ถ้ามี): {{ $json.displayName || 'ลูกค้าท่านนี้' }}\nเพิ่มเติม: ถ้ามี [ข้อมูลจากฐานความรู้] แนบมา ให้ใช้ข้อมูลนั้นตอบเป็นหลัก (อ้างอิงสั้น ๆ ได้)";
const chj = $('Shape Channel FB').first().json;
const perj = (chj.persona_system || '').trim();
let sys;
if (perj) { sys = perj; }
else { sys = SYSJS; sys = sys.replace(/^=/, '').split("{{ $json.displayName || 'ลูกค้าท่านนี้' }}").join(dn); }
sys += ' /no_think';
const sqlBlock = (a.sql_block || '');
const content = (a.text || '') + '\n\n[ข้อมูลจากฐานความรู้ RAG — ใช้ประกอบการตอบ ถ้าไม่เกี่ยวให้ตอบตามปกติ]:\n' + (a.rag_context || '')
  + (sqlBlock ? '\n\n[ข้อมูลสดจากฐานข้อมูลร้าน — ข้อเท็จจริง ต้องยึดตัวเลขราคา/สต็อก/ชื่อร้านตามนี้เท่านั้น ห้ามดึงตัวเลขจากแถวอื่นหรือแต่ง spec เพิ่ม]:\n' + sqlBlock : '');
return [{ json: { system: sys, messages: [{ role: 'user', content: content }] } }];

const q = ($('Webhook').first().json.query || {});
const cfg = $('Set Config').first().json;
const okMode = (q['hub.mode'] || '') === 'subscribe';
const tok = (q['hub.verify_token'] || '').toString();
const okToken = tok !== '' && tok === ((cfg.VERIFY_TOKEN || '').toString());
return [{ json: { verified: okMode && okToken } }];
